				dttt += (_ref->__dh[2][s] * _ref->buf_v[s]) * _ref->get__gi(1, 1) * v2 * v1 * v2;
				//dttt += (_ref->__dh[3][s] * _ref->buf_u[s]) * _ref->get__gi(0, 0) * v2 * v2 * v1;
				dttt += (_ref->__dh[3][s] * _ref->buf_v[s]) * _ref->get__gi(0, 1) * v2 * v2 * v1;
