			t1 /= length; t2 /= length;
			length = sqrt(n1 * n1 * _ref->get__gij(0, 0) + 2 * n1 * n2 * _ref->get__gij(0, 1) + n2 * n2 * _ref->get__gij(1, 1));
			n1 /= length; n2 /= length;



			double S1 = 0, S2 = 0;
