					double _f11 = -_Gamma111 * phi1 - _Gamma112 * phi2;
					double _f12 = -_Gamma121 * phi1 - _Gamma122 * phi2;
					double _f22 = -_Gamma221 * phi1 - _Gamma222 * phi2;

