				{
					xu += _ref->d1[0][s] * _ref->buf_u[s];
					xv += _ref->d1[1][s] * _ref->buf_u[s];
					yu += _ref->d1[0][s] * _ref->buf_v[s];
					yv += _ref->d1[1][s] * _ref->buf_v[s];
				}
				double duu = xu * _ref->get__gi(0, 0) + yu * _ref->get__gi(0, 1);
