			double E21 = w1 * (v2 * v1) + w2 * (s2 * s1);
			double E22 = w1 * (v2 * v2) + w2 * (s2 * s2);
			double S11 = get__Sij(0, 0);
			double S12 = get__Sij(0, 1);
