			v1 /= length;
			v2 /= length;
			length = sqrt(w1 * w1 * _ref->get__gij(0, 0) + 2 * w1 * w2 * _ref->get__gij(0, 1) + w2 * w2 * _ref->get__gij(1, 1));
			w1 /= length;
