			double	hz = get_gi2(1, 2);


			double Nx = gy * hz - gz * hy;
			double Ny = gz * hx - gx * hz;
			double Nz = gx * hy - gy * hx;
			double  norm = sqrt(Nx * Nx + Ny * Ny + Nz * Nz);
			Nx = Nx / norm;
			Ny = Ny / norm;
			Nz = Nz / norm;
			N[0] = Nx;
			N[1] = Ny;
			N[2] = Nz;

