				double _dvv = _xv * _ref->_ogi2[3] + _yv * _ref->_ogi2[4] + _zv * _ref->_ogi2[5];

				double _S11 = _duu;
				double _S12 = (_duv + _dvu) * 0.5;
				double _S21 = _S12;
