			double E22 = w1 * (v2 * v2) + w2 * (s2 * s2);
			str += "E11=" + std::to_string(E11) + "\n";
			str += "E12=" + std::to_string(E12) + "\n";
			str += "E22=" + std::to_string(E22) + "\n";
