				double _g21 = _g12;

				double _E11 = _g22 * _ref->osc2;
				double _E12 = -_g12 * _ref->osc2;
				double _E22 = _g11 * _ref->osc2;
				double _E21 = _E12;


				//val = (S11 * E11 * _X12 + S11 * E12 * _X22 + S12 * E21 * _X12 + S12 * E22 * _X22) * scale;
