				_Nz /= _ref->orefDv;
				_S11 += x11 * _Nx + y11 * _Ny + z11 * _Nz;
				_S12 += x12 * _Nx + y12 * _Ny + z12 * _Nz;
				_S22 += x22 * _Nx + y22 * _Ny + z22 * _Nz;
				double _g11 = 2 * _ref->d1[0][s] * get_gi2(0, 0);
				double _g12 = _ref->d1[0][s] * get_gi2(1, 0) + _ref->d1[1][s] * get_gi2(0, 0);
