			Nx /= _ref->orefDv;
			Ny /= _ref->orefDv;
			Nz /= _ref->orefDv;
			double S11 = X11 * Nx + Y11 * Ny + Z11 * Nz;
			double S12 = X12 * Nx + Y12 * Ny + Z12 * Nz;
			double S22 = X22 * Nx + Y22 * Ny + Z22 * Nz;
