				X12 += _ref->d2[1][s] * _ref->node[s * 3 + 0];
				X22 += _ref->d2[3][s] * _ref->node[s * 3 + 0];
				Y11 += _ref->d2[0][s] * _ref->node[s * 3 + 1];
				Y12 += _ref->d2[1][s] * _ref->node[s * 3 + 1];
				Y22 += _ref->d2[3][s] * _ref->node[s * 3 + 1];
