			e11 = e1x * e1x + e1y * e1y + e1z * e1z;
			e12 = e1x * e2x + e1y * e2y + e1z * e2z;
			e22 = e2x * e2x + e2y * e2y + e2z * e2z;
			double e21 = e12;
			
			double E11 = e22 * _ref->osc;
			double E12 = -e12 * _ref->osc;
