			double E21 = -get_gij2(0, 1) * _ref->osc;;
			double E22 = get_gij2(0, 0) * _ref->osc;;



			double h11 = 0, h12 = 0, h22 = 0;

			h11 = get___hij(0, 0);
			h12 = get___hij(0, 1);
			h22 = get___hij(1, 1);

