				//Y12 += _ref->___dh[1][s] * _ref->node[s * 3 + 1];
				//Y22 += _ref->___dh[3][s] * _ref->node[s * 3 + 1];
				Z11 += _ref->__dh[0][s] * _ref->buf_z[s];
