			double E12 = w1 * (v1 * v2) + w2 * (s1 * s2);
			double E21 = w1 * (v2 * v1) + w2 * (s2 * s1);
			double E22 = w1 * (v2 * v2) + w2 * (s2 * s2);
			double S11 = get___Sij(0, 0);
			double S12 = get___Sij(0, 1);
			double S22 = get___Sij(1, 1);
			double S21 = S12;

