				_S11 += X11 * _Nx + Y11 * _Ny + Z11 * _Nz;
				_S12 += X12 * _Nx + Y12 * _Ny + Z12 * _Nz;
				_S22 += X22 * _Nx + Y22 * _Ny + Z22 * _Nz;
				double _S21 = _S12;
				double _g11 = 2 * _ref->d1[0][s] * get_gi(0, 0);
