			double S22 = X22 * Nx + Y22 * Ny + Z22 * Nz;
			double S21 = S12;
			double L2 = v1 * v1 * get_gij(0, 0) + 2 * v1 * v2 * get_gij(0, 1) + v2 * v2 * get_gij(1, 1);
			double w2 = -get_gij(0, 0) * v1 - get_gij(0, 1) * v2;
