			double usss = u111 * s1 * s1 * s1 + u112 * s1 * s1 * s2 + 2 * (u121 * s1 * s2 * s1 + u122 * s1 * s2 * s2) + u221 * s2 * s2 * s1 + u222 * s2 * s2 * s2;
			double vsss = v111 * s1 * s1 * s1 + v112 * s1 * s1 * s2 + 2 * (v121 * s1 * s2 * s1 + v122 * s1 * s2 * s2) + v221 * s2 * s2 * s1 + v222 * s2 * s2 * s2;

