				double _xu = _ref->d1[0][s];
				double _xv = _ref->d1[1][s];
				double _yu = 0;// _ref->d1[0][s];
				double _yv = 0;// _ref->d1[1][s];

				double _duu = _xu * _ref->_ogi[0] + _yu * _ref->_ogi[1];
