				double _tr = _duu * _ref->oG11 + _duv * _ref->oG12 + _dvu * _ref->oG12 + _dvv * _ref->oG22;

				double _h11 = (2 * _duu) - _tr * _ref->og11;
				double _h12 = (_duv + _dvu) - _tr * _ref->og12;
