					double _Gamma221 = _ref->__dh[6][s] * get_Gi(0, 0);
					double _Gamma222 = _ref->__dh[7][s] * get_Gi(1, 0);

					double _Suu = -_Gamma111 * z1 - _Gamma112 * z2;
					double _Suv = -_Gamma121 * z1 - _Gamma122 * z2;
					double _Svv = -_Gamma221 * z1 - _Gamma222 * z2;
