				h11 = get__hij(0, 0);
				h12 = get__hij(0, 1);
				h22 = get__hij(1, 1);


				double Huu = h22 * _ref->osc;
				double Huv = -h12 * _ref->osc;
				double Hvv = h11 * _ref->osc;

				double Suu = 0, Suv = 0, Svv = 0;


				Suu = get__Sij(0, 0);
				Suv = get__Sij(0, 1);
				Svv = get__Sij(1, 1);
				double* ptr1 = ptr;
