			double _h21 = (_duv + _dvu);
			double _h22 = (2 * _dvv);
				double _H11 = _h22 * _ref->osc, _H22 = _h11 * _ref->osc, _H12 = -_h12 * _ref->osc;

				val = (_H11 * Suu + 2 * _H12 * Suv + _H22 * Svv);// *iJ;
