				double tr = duu * _ref->oG11 + duv * _ref->oG12 + dvu * _ref->oG12 + dvv * _ref->oG22;

				double huu = (2 * duu) - tr * _ref->og11;
				double huv = (duv + dvu) - tr * _ref->og12;
