		double norm(double d1, double d2) {
			double x = __mem->get_Gi(0, 0) * d1 + __mem->get_Gi(1, 0) * d2;
			double y = __mem->get_Gi(0, 1) * d1 + __mem->get_Gi(1, 1) * d2;
			double z = __mem->get_Gi(0, 2) * d1 + __mem->get_Gi(1, 2) * d2;
			return sqrt(x * x + y * y + z * z);
		}
		
